async function patchFiles(
  { workspace: { read, edit } },
  input: { patches: { file: string; replace: [string, string][] }[] },
) {
  const out: { file: string; revision: string | null }[] = [];
  const prepared: { file: string; revision: string; content: string }[] = [];
  for (const patch of input.patches) {
    const current = await read(patch.file, { format: "raw" });
    if (current.truncated || current.hasMore) throw new Error(`${patch.file} read was partial`);
    let content = current.content;
    for (const [before, after] of patch.replace) {
      const count = content.split(before).length - 1;
      if (count !== 1)
        throw new Error(
          `${patch.file}: expected one match, found ${count}: ${before.slice(0, 80)}`,
        );
      content = content.replace(before, () => after);
    }
    prepared.push({ file: patch.file, revision: current.revision, content });
  }
  for (const p of prepared) {
    const r = await edit(p.file, {
      revision: p.revision,
      changes: [{ kind: "replaceFile", content: p.content }],
    });
    out.push({ file: p.file, revision: r.revision });
  }
  return out;
}
